import os
import unicodedata
from flask import Flask, request, jsonify, session
from functools import wraps
import hashlib
import hmac
import re

app = Flask(__name__)
app.secret_key = os.urandom(32)

BASE_DIR = '/srv/shared_files'
RESTRICTED_DIRS = {'/srv/shared_files/admin', '/srv/shared_files/config', '/srv/shared_files/secrets'}

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'user' not in session:
            return jsonify({'error': 'unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

def is_safe_path_component(component):
    """Check if a single path component is safe (no traversal sequences)"""
    if component in ('.', '..', ''):
        return False
    if '/' in component or '\\' in component:
        return False
    return True

def check_access(filepath, user_role):
    """Verify user has access to the requested file path.
    Returns (allowed: bool, resolved_path: str)
    """
    # Split into components and validate each
    components = filepath.split('/')
    for comp in components:
        if comp == '':
            continue
        if not is_safe_path_component(comp):
            return False, None

    # Build the target path
    target = os.path.join(BASE_DIR, filepath)

    # Check against restricted directories
    if user_role != 'admin':
        for restricted in RESTRICTED_DIRS:
            if target.startswith(restricted):
                return False, None

    return True, target

def sanitize_filename(filename):
    """Normalize unicode in filename for consistent filesystem access.
    NFKC normalization ensures compatibility equivalents are unified.
    """
    return unicodedata.normalize('NFKC', filename)

@app.route('/api/files/read', methods=['POST'])
@require_auth
def read_file():
    data = request.get_json()
    if not data or 'path' not in data:
        return jsonify({'error': 'path required'}), 400

    filepath = data['path']
    user_role = session.get('role', 'user')

    # Step 1: Normalize unicode BEFORE any security checks
    filepath = sanitize_filename(filepath)

    # Step 2: Authorization check on the normalized path
    allowed, target = check_access(filepath, user_role)
    if not allowed:
        return jsonify({'error': 'access denied'}), 403

    # Step 3: Resolve to absolute path for safety
    final_path = os.path.realpath(target)

    # Step 4: Verify still within base directory
    if not final_path.startswith(BASE_DIR):
        return jsonify({'error': 'access denied'}), 403

    # Step 5: Re-check restricted dirs on final resolved path
    if user_role != 'admin':
        for restricted in RESTRICTED_DIRS:
            if final_path.startswith(restricted):
                return jsonify({'error': 'access denied'}), 403

    try:
        with open(final_path, 'r') as f:
            content = f.read(4096)
        return jsonify({'content': content, 'path': filepath})
    except FileNotFoundError:
        return jsonify({'error': 'not found'}), 404
    except PermissionError:
        return jsonify({'error': 'permission denied'}), 403

@app.route('/api/files/list', methods=['POST'])
@require_auth
def list_files():
    data = request.get_json()
    if not data or 'path' not in data:
        return jsonify({'error': 'path required'}), 400

    filepath = data['path']
    user_role = session.get('role', 'user')

    # Normalize BEFORE checks
    filepath = sanitize_filename(filepath)

    allowed, target = check_access(filepath, user_role)
    if not allowed:
        return jsonify({'error': 'access denied'}), 403

    final_path = os.path.realpath(target)

    if not final_path.startswith(BASE_DIR):
        return jsonify({'error': 'access denied'}), 403

    if user_role != 'admin':
        for restricted in RESTRICTED_DIRS:
            if final_path.startswith(restricted):
                return jsonify({'error': 'access denied'}), 403

    try:
        entries = os.listdir(final_path)
        return jsonify({'entries': entries, 'path': filepath})
    except (FileNotFoundError, NotADirectoryError):
        return jsonify({'error': 'not found'}), 404

@app.route('/api/auth/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'invalid request'}), 400
    username = data.get('username', '')
    password = data.get('password', '')
    # Simplified auth for demonstration
    if username == 'admin' and hmac.compare_digest(password, os.environ.get('ADMIN_PASS', '')):
        session['user'] = username
        session['role'] = 'admin'
    elif username and password:
        session['user'] = username
        session['role'] = 'user'
    else:
        return jsonify({'error': 'invalid credentials'}), 401
    return jsonify({'status': 'ok', 'role': session['role']})

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080)
